  document.querySelectorAll("[data-output-path]").forEach(el=>{let value=get(el.dataset.outputPath);if(value===undefined&&el.dataset.outputFallbackPath)value=get(el.dataset.outputFallbackPath);const format=el.dataset.outputFormat;el.textContent=format==="money"?money(value):format==="percent"?`${number(Number(value||0)*100)}%`:format==="text"?String(value||"—"):number(value)});
  document.querySelectorAll("[data-table-cell][data-path]:not([data-draft])").forEach(el=>{if(el===document.activeElement||el.getAttribute("aria-invalid")==="true"||state.ui.pendingCells.get(el.dataset.tableId,el.dataset.rowId,el.dataset.field))return;const value=get(el.dataset.path),column=tableColumn(el.dataset.tableId,el.dataset.field);if(el.type==="checkbox")el.checked=Boolean(value);else if(column?.type==="currency"&&value!==null&&value!==undefined&&value!=="")el.value=Number(value).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});else el.value=value??""});
