async function deleteRow(spec){
  const split=spec.lastIndexOf(":"),path=spec.slice(0,split),index=Number(spec.slice(split+1)),prior=get(path)?.[index];
  if(!prior)return;
  if(path==="cost_codes"){
    try{
      await ensureSaved();
      let result=await api(`/api/projects/${state.doc.project.id}/cost-codes/${encodeURIComponent(prior.id)}/remove`,{method:"POST",body:JSON.stringify({expected_revision:state.doc.project.revision,confirm_cascade:false,reason:"Cost Code removal requested"})});
      if(result.requires_confirmation){
        const report=result.dependency_report||{},entries=Object.entries(report).filter(([,value])=>Number(value)||Array.isArray(value)&&value.length),confirmed=await dialogForm("Remove Cost Code",`<p>Associated detail exists:</p><ul>${entries.map(([label,value])=>`<li>${esc(label.replaceAll("_"," "))}: ${Array.isArray(value)?value.length:value}</li>`).join("")}</ul><p>Continuing removes this working detail. Immutable history remains unchanged.</p>`,"Remove code and detail");
        if(!confirmed)return;
        result=await api(`/api/projects/${state.doc.project.id}/cost-codes/${encodeURIComponent(prior.id)}/remove`,{method:"POST",body:JSON.stringify({expected_revision:state.doc.project.revision,confirm_cascade:true,reason:"User-confirmed Cost Code cascade removal"})});
      }
      if(result.removed===false){toast("Cost Code was not removed.",true);return}
      state.doc=result.project;render();toast("Cost Code removed");
    }catch(error){toast(error.message,true)}
    return;
  }
  if(!confirm("Remove this working record? Submitted and awarded snapshots remain unchanged."))return;
  if(path==="labor_estimates"&&(prior.origin==="automatic"||prior.source_links?.length)){
    state.doc.working_estimate.labor_suggestion_exclusions??=[];
    const exclusions=state.doc.working_estimate.labor_suggestion_exclusions,normalized=String(prior.code||"").trim();
    if(normalized&&!exclusions.some(code=>String(code).toLowerCase()===normalized.toLowerCase())){const before=[...exclusions];exclusions.push(normalized);markDirty({path:"working_estimate.labor_suggestion_exclusions",prior:before,new:[...exclusions],reason:"Automatic Labor suggestion excluded"})}
  }
  get(path).splice(index,1);markDirty({path:`${path}.${index}`,prior,new:null,reason:"Record removed"});render();
}
